content.css:
.table-container {
  overflow: auto;
  padding: 15px;
  box-sizing: border-box;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
  height: 100%;
  width: 100%;
}
/* Custom scrollbars to prevent the native Chromium scrollbar from 
   creating fractional pixel offsets that blur the text when scaled */
.table-container::-webkit-scrollbar {
  width: 12px;
  height: 12px;
}
.table-container::-webkit-scrollbar-track {
  background: transparent;
}
.table-container::-webkit-scrollbar-thumb {
  background-color: rgba(153, 153, 153, 0.5);
  border-radius: 6px;
  border: 3px solid transparent;
  background-clip: padding-box;
}
.table-container::-webkit-scrollbar-thumb:hover {
  background-color: rgba(102, 102, 102, 0.8);
}
.table-container::-webkit-scrollbar-corner {
  background: transparent;
}
.pbi-table {
  border-collapse: separate;
  border-spacing: 0;
  table-layout: fixed;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  font-size: 14px;
  background-color: #ffffff;
}
.table-header-row {
  background-color: #f0f0f0;
}
.table-header-cell {
  padding: 0 12px;
  text-align: left;
  font-weight: bold;
  color: #333;
  border-right: 1px solid #d0d0d0;
  display: table-cell;
  vertical-align: middle;
  position: relative;
  transition: opacity 0.15s ease-in-out;
}
.table-header-cell:last-child {
  border-right: none;
}
.resize-handle {
  position: absolute;
  right: 0;
  top: 0;
  bottom: 0;
  width: 5px;
  cursor: col-resize;
  z-index: 500;
}
.resize-handle:hover {
  background-color: rgba(0, 120, 212, 0.3);
}
.sort-icon {
  display: inline-block;
  padding: 1px 4px;
  font-size: 0.9em;
  line-height: 1;
  cursor: pointer;
  user-select: none;
  opacity: 0.85;
  color: #555;
  background-color: rgba(0, 0, 0, 0.04);
  border: 1px solid rgba(0, 0, 0, 0.12);
  vertical-align: middle;
  transition: opacity 0.15s ease-in-out, background-color 0.15s ease-in-out, color 0.15s ease-in-out, border-color 0.15s ease-in-out;
  border-radius: 3px;
  z-index: 2;
}
.sort-icon:hover {
  opacity: 1;
  background-color: rgba(0, 120, 212, 0.18);
  border-color: rgba(0, 120, 212, 0.5);
  color: #0078d4;
}
.sort-icon.sort-icon-active {
  opacity: 1;
  color: #ffffff;
  background-color: #0078d4;
  border-color: #0078d4;
}
.sort-icon.sort-icon-inline {
  position: static;
}
.sort-icon.sort-icon-inline.sort-icon-align-left {
  float: left;
  margin-right: 6px;
  margin-left: 0;
}
.sort-icon.sort-icon-inline.sort-icon-align-right {
  float: right;
  margin-left: 6px;
  margin-right: 0;
}
.sort-icon.sort-icon-inline.sort-icon-align-center {
  float: right;
  margin-left: 6px;
}
.sort-icon.sort-icon-overlay {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
}
.sort-icon.sort-icon-overlay.sort-icon-align-left {
  left: 4px;
  right: auto;
}
.sort-icon.sort-icon-overlay.sort-icon-align-right {
  right: 8px;
  left: auto;
}
.sort-icon.sort-icon-overlay.sort-icon-align-center {
  left: 50%;
  transform: translate(-50%, -50%);
  right: auto;
}
.table-data-row {
  border-bottom: 1px solid #e0e0e0;
  transition: opacity 0.15s ease-in-out;
}
.table-data-row:hover {
  background-color: #f9f9f9;
}
.table-category-cell {
  padding: 0 12px;
  font-weight: 500;
  color: #333;
  border-right: 1px solid #e0e0e0;
  background-color: #f5f5f5;
  display: table-cell;
  vertical-align: middle;
  transition: opacity 0.15s ease-in-out;
}
.table-data-cell {
  padding: 0 12px;
  text-align: right;
  color: #333;
  border-right: 1px solid #e0e0e0;
  display: table-cell;
  vertical-align: middle;
  transition: opacity 0.15s ease-in-out;
}
.table-data-cell:last-child {
  border-right: none;
}
.column-dimmed {
  opacity: 0.3;
}
.table-total-row {
  background-color: #e8e8e8;
  border-top: 2px solid #999;
  border-bottom: 2px solid #999;
}
.table-total-label-cell {
  padding: 0 12px;
  color: #333;
  border-right: 1px solid #999;
  display: table-cell;
  vertical-align: middle;
  text-underline-offset: 4px;
  text-decoration-thickness: 1px;
}
.table-total-cell {
  padding: 0 12px;
  text-align: right;
  color: #333;
  border-right: 1px solid #999;
  display: table-cell;
  vertical-align: middle;
  text-underline-offset: 4px;
  text-decoration-thickness: 1px;
}
.table-total-cell:last-child {
  border-right: none;
}
/* -- Accessibility -------------------------------------------------------- */
/* Visible keyboard focus indicator on grid + cells */
.pbi-table:focus {
  outline: 2px solid #0078d4;
  outline-offset: -2px;
}
.pbi-table [role="gridcell"]:focus,
.pbi-table [role="columnheader"]:focus,
.pbi-table [role="rowheader"]:focus {
  outline: 2px solid #0078d4;
  outline-offset: -2px;
  position: relative;
  z-index: 300;
}
/* Windows High Contrast / forced-colors mode (WCAG 2.4.7, certified-visual req) */
@media (forced-colors: active) {
  .table-container {
    background-color: Canvas;
    color: CanvasText;
    forced-color-adjust: none;
  }
  .pbi-table,
  .pbi-table th,
  .pbi-table td,
  .table-header-row,
  .table-data-row,
  .table-total-row,
  .table-header-cell,
  .table-category-cell,
  .table-data-cell,
  .table-total-label-cell {
    background-color: Canvas !important;
    color: CanvasText !important;
    border-color: CanvasText !important;
    forced-color-adjust: none;
  }
  .pbi-table:focus,
  .pbi-table [role="gridcell"]:focus,
  .pbi-table [role="columnheader"]:focus,
  .pbi-table [role="rowheader"]:focus {
    outline: 2px solid Highlight !important;
    background-color: Highlight !important;
    color: HighlightText !important;
  }
  .resize-handle:hover {
    background-color: Highlight !important;
  }
  /* Selection dimming uses opacity, which forced-colors honours; nothing to override */
}
